// Individual Stomach component with internal animations
const Stomach: React.FC<{
  index: number;
  label: string;
  liquidColor: string;
  liquidHeight: number;
  items: React.ReactNode;
  frame: number;
  fps: number;
  width: number;
  height: number;
}> = ({ index, label, liquidColor, liquidHeight, items, frame, fps, width, height }) => {
  const startFrame = 35 + index * 18;
  const activeFrame = frame - startFrame;

  const scaleSpring = spring({
    frame: activeFrame,
    fps,
    config: { damping: 11, stiffness: 100 },
  });
  
  const scale = interpolate(activeFrame, [0, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const currentScale = scaleSpring * scale;
  
  // Continuous float loop after entrance resolves
  const floatOffset = activeFrame > 35 
    ? Math.sin((frame - startFrame - 35) * 0.07) * 4 
    : 0;

  // Liquid Rise Spring
  const fillProgress = spring({
    frame: activeFrame - 8,
    fps,
    config: { damping: 14, stiffness: 70 },
  });
  const currentFill = interpolate(fillProgress, [0, 1], [0, liquidHeight], { extrapolateRight: "clamp" });
  const liquidY = 200 - (currentFill * 175);

  // Food Dropping Animation
  const foodDropProgress = spring({
    frame: activeFrame - 15,
    fps,
    config: { damping: 12, stiffness: 80 },
  });
  const foodYOffset = interpolate(foodDropProgress, [0, 1], [-90, 0], { extrapolateRight: "clamp" });
  const foodOpacity = interpolate(foodDropProgress, [0, 0.3], [0, 1], { extrapolateRight: "clamp" });

  // Adjusted horizontal margins to prevent clipping at edges (using 12% to 88%)
  const usableWidth = width * 0.76;
  const startX = width * 0.12;
  const step = usableWidth / 4;
  const x = startX + index * step;

  const stomachWidth = width * 0.13;
  const stomachHeight = stomachWidth * (200 / 150);

  // Label stagger in
  const labelScale = spring({
    frame: activeFrame - 22,
    fps,
    config: { damping: 10, stiffness: 120 },
  });
  const labelOpacity = interpolate(activeFrame - 22, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  return (
    <div
      style={{
        position: "absolute",
        left: x - stomachWidth / 2,
        top: height * 0.34 + floatOffset,
        width: stomachWidth,
        height: stomachHeight + 80,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transform: `scale(${currentScale})`,
        opacity: scale,
        transformOrigin: "bottom center",
        transition: "none",
      }}
    >
      <div style={{ width: stomachWidth, height: stomachHeight, transition: "none" }}>
        <svg 
          width="100%" 
          height="100%" 
          viewBox="0 0 150 200" 
          style={{ overflow: "visible", filter: "drop-shadow(0px 8px 16px rgba(0,0,0,0.12))", transition: "none" }}
        >
          <defs>
            <clipPath id={`stomach-clip-${index}`}>
              <path d={stomachPath} />
            </clipPath>
          </defs>

          {/* Background White Stomach Wall */}
          <path 
            d={stomachPath} 
            fill="#ffffff" 
            stroke="#1d2d2a" 
            strokeWidth="5" 
            strokeLinejoin="round"
          />

          {/* Liquid and Food Contents (clipped) */}
          <g clipPath={`url(#stomach-clip-${index})`}>
            <rect 
              x="-10" 
              y={liquidY} 
              width="170" 
              height="210" 
              fill={liquidColor} 
              style={{ transition: "none" }}
            />
            {/* Subtle Liquid Surface Wave Line */}
            <path 
              d={`M -10,${liquidY} Q 30,${liquidY - 4} 75,${liquidY} T 160,${liquidY}`} 
              fill="none" 
              stroke="rgba(255,255,255,0.3)" 
              strokeWidth="2.5" 
            />
            
            <g style={{ transform: `translate(0px, ${foodYOffset}px)`, opacity: foodOpacity, transition: "none" }}>
              {items}
            </g>
          </g>

          {/* Front crisp border overlay */}
          <path 
            d={stomachPath} 
            fill="none" 
            stroke="#1d2d2a" 
            strokeWidth="5" 
            strokeLinejoin="round"
            strokeLinecap="round"
          />

          {/* Depth detail crescent */}
          <path
            d="M 115,65 C 120,85 115,105 107,112"
            fill="none"
            stroke="#1d2d2a"
            strokeWidth="3"
            strokeLinecap="round"
            opacity="0.15"
          />
        </svg>
      </div>

      {/* Label Text below the stomach */}
      <div
        style={{
          marginTop: 22,
          color: "#1d2d2a",
          fontSize: Math.max(12, width * 0.011),
          fontWeight: 900,
          textAlign: "center",
          textTransform: "uppercase",
          letterSpacing: "1px",
          width: "140%",
          lineHeight: 1.25,
          transform: `scale(${labelScale})`,
          opacity: labelOpacity,
          transition: "none",
        }}
      >
        {label}
      </div>
    </div>
  );
};

// Header Sparkle / Glitter asset animation
const Sparkles: React.FC<{ frame: number }> = ({ frame }) => {
  const scale = spring({
    frame: frame - 15,
    fps: 30,
    config: { damping: 8, stiffness: 150 },
  });
  
  const pulse = Math.sin(frame * 0.1) * 0.05 + 1;

  return (
    <svg 
      width="32" 
      height="32" 
      viewBox="0 0 30 30" 
      style={{
        transform: `scale(${scale * pulse})`,
        transformOrigin: "bottom left",
        marginLeft: 12,
        display: "inline-block",
        verticalAlign: "super",
        transition: "none",
      }}
    >
      <path d="M 5,25 Q 8,12 18,8" fill="none" stroke="#FFD54F" strokeWidth="3" strokeLinecap="round" />
      <path d="M 5,25 Q 15,18 25,20" fill="none" stroke="#FFD54F" strokeWidth="3" strokeLinecap="round" />
      <path d="M 5,25 Q 18,22 24,28" fill="none" stroke="#FFD54F" strokeWidth="3" strokeLinecap="round" />
    </svg>
  );
};

// Main Schema


export type CalorieDensityProps = Record<string, any>;

const CalorieDensity: React.FC<CalorieDensityProps> = ({
  backgroundColor = "#244d42",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "CALORIE DENSITY",
  subtitleText = "WHAT 500 CALORIES LOOK LIKE",
  oilLabel = "OIL",
  cheeseLabel = "CHEESE",
  meatLabel = "MEAT",
  carbsLabel = "POTATOES, BEANS, RICE",
  veggiesLabel = "FRUITS & VEGGIES",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Add robust horizontal padding (12% margin from edges) to safe zone bounds
  const leftBound = width * 0.12;
  const rightBound = width * 0.88;
  const timelineY = height * 0.88;

  // Title entrance animations
  const titleY = interpolate(frame, [0, 20], [-40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  const subtitleY = interpolate(frame, [8, 28], [30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const subtitleOpacity = interpolate(frame, [8, 28], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Timeline / Progress Bar Track Animation
  const timelineProgress = interpolate(frame, [35, 115], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentTimelineX = leftBound + timelineProgress * (rightBound - leftBound);

  // Colors of timeline circles matching the stomach densities
  const nodeColors = ["#FBC02D", "#FFF176", "#E57373", "#7986CB", "#4CAF50"];

  // Midpoints for Arrowheads along the timeline segments
  const arrowPositions = [0.5, 1.5, 2.5, 3.5].map(step => {
    const stepSize = (width * 0.76) / 4;
    return leftBound + step * stepSize;
  });

  return (
    <AbsoluteFill 
      style={{ 
        background: transparentBackground ? "transparent" : `radial-gradient(circle, ${finalBgColor}ee 0%, #0d1a16 100%)`, 
        fontFamily,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Upper Title Block */}
      <div 
        style={{
          textAlign: "center",
          marginTop: height * 0.07,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          zIndex: 10,
          transition: "none",
        }}
      >
        <h1 
          style={{
            color: "#ffffff",
            fontSize: height * 0.065,
            fontWeight: 900,
            margin: 0,
            letterSpacing: "3px",
            display: "flex",
            alignItems: "center",
            textShadow: "0 4px 12px rgba(0,0,0,0.15)",
            transform: `translateY(${titleY}px)`,
            opacity: titleOpacity,
            transition: "none",
          }}
        >
          {titleText}
          <Sparkles frame={frame} />
        </h1>
        <h2 
          style={{
            color: "#111b18",
            fontSize: height * 0.040,
            fontWeight: 800,
            margin: 0,
            marginTop: 4,
            letterSpacing: "1.5px",
            transform: `translateY(${subtitleY}px)`,
            opacity: subtitleOpacity,
            transition: "none",
          }}
        >
          {subtitleText}
        </h2>
      </div>

      {/* 5 Animated Stomachs with safe paddings (liquid levels increased for better visibility) */}
      <Stomach 
        index={0} 
        label={oilLabel} 
        liquidColor="#FFD54F" 
        liquidHeight={0.20} 
        items={<OilItems />} 
        frame={frame} 
        fps={fps} 
        width={width} 
        height={height} 
      />
      <Stomach 
        index={1} 
        label={cheeseLabel} 
        liquidColor="#FFF59D" 
        liquidHeight={0.45} 
        items={<CheeseItems />} 
        frame={frame} 
        fps={fps} 
        width={width} 
        height={height} 
      />
      <Stomach 
        index={2} 
        label={meatLabel} 
        liquidColor="#EF5350" 
        liquidHeight={0.50} 
        items={<MeatItems />} 
        frame={frame} 
        fps={fps} 
        width={width} 
        height={height} 
      />
      <Stomach 
        index={3} 
        label={carbsLabel} 
        liquidColor="#7986CB" 
        liquidHeight={0.68} 
        items={<CarbsItems />} 
        frame={frame} 
        fps={fps} 
        width={width} 
        height={height} 
      />
      <Stomach 
        index={4} 
        label={veggiesLabel} 
        liquidColor="#81C784" 
        liquidHeight={0.88} 
        items={<VeggieItems />} 
        frame={frame} 
        fps={fps} 
        width={width} 
        height={height} 
      />

      {/* Progress Timeline Navigation at Bottom */}
      <svg 
        width="100%" 
        height="100%" 
        style={{ position: "absolute", inset: 0, pointerEvents: "none", overflow: "visible", transition: "none" }}
      >
        <defs>
          <linearGradient id="timeline-grad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#FBC02D" />
            <stop offset="25%" stopColor="#FFF176" />
            <stop offset="50%" stopColor="#FFF176" />
            <stop offset="75%" stopColor="#7986CB" />
            <stop offset="100%" stopColor="#4CAF50" />
          </linearGradient>
        </defs>

        {/* Timeline Track Base */}
        <line 
          x1={leftBound} 
          y1={timelineY} 
          x2={rightBound} 
          y2={timelineY} 
          stroke="#1d3d34" 
          strokeWidth="4" 
          strokeLinecap="round" 
        />

        {/* Colored Active Track (Reveals left to right) */}
        <line 
          x1={leftBound} 
          y1={timelineY} 
          x2={currentTimelineX} 
          y2={timelineY} 
          stroke="url(#timeline-grad)" 
          strokeWidth="4" 
          strokeLinecap="round" 
        />

        {/* Segment Directional Arrows */}
        {arrowPositions.map((arrowX, i) => {
          const arrowTriggerFrame = 35 + (i + 0.5) * 18;
          const isPassed = frame >= arrowTriggerFrame;
          const arrowScale = spring({
            frame: isPassed ? frame - arrowTriggerFrame : 0,
            fps,
            config: { damping: 7, stiffness: 120 },
          });

          return (
            <g 
              key={i} 
              transform={`translate(${arrowX}, ${timelineY}) scale(${isPassed ? arrowScale : 0})`}
              style={{ transition: "none" }}
            >
              <path 
                d="M -3,-5 L 2,0 L -3,5" 
                fill="none" 
                stroke="#a1e4c7" 
                strokeWidth="3.5" 
                strokeLinecap="round" 
                strokeLinejoin="round"
              />
            </g>
          );
        })}

        {/* Timeline Node Points */}
        {Array.from({ length: 5 }).map((_, i) => {
          const usableWidth = width * 0.76;
          const startX = width * 0.12;
          const step = usableWidth / 4;
          const nodeX = startX + i * step;

          const nodeTriggerFrame = 35 + i * 18;
          const nodeActiveFrame = frame - nodeTriggerFrame;
          const isNodeActive = nodeActiveFrame > 0;

          const nodeScale = spring({
            frame: nodeActiveFrame,
            fps,
            config: { damping: 9, stiffness: 130 },
          });
          const nodeOpacity = interpolate(nodeActiveFrame, [0, 10], [0, 1], { extrapolateRight: "clamp" });

          return (
            <g 
              key={i} 
              transform={`translate(${nodeX}, ${timelineY})`}
              style={{ opacity: isNodeActive ? nodeOpacity : 0.25, transition: "none" }}
            >
              {/* Outer Ring */}
              <circle 
                cx="0" 
                cy="0" 
                r="11" 
                fill="#111b18" 
                stroke={nodeColors[i]} 
                strokeWidth="3.5" 
              />
              
              {/* Solid colored inner dot */}
              <circle 
                cx="0" 
                cy="0" 
                r={isNodeActive ? 6.5 * nodeScale : 0} 
                fill={nodeColors[i]} 
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default CalorieDensity;